// Generates src/content/lastmod.generated.ts: route path -> the date its VIEW file last
// changed in git. Fixes the sitemap freshness problem found in the 2026-08-31 audit: all
// 587 URLs carried one identical build-time lastmod, telling Google nothing about which
// pages actually changed and spending the freshness signal on all of them at once.
//
// Runs LOCALLY only (wired into prebuild but fail-soft): the Hostinger deploy archive
// excludes .git, so on the server this script finds no git and keeps the committed file
// as-is. The generated file is therefore COMMITTED, not gitignored - like
// redirects.generated.ts at the repo root and unlike the data/seo.json-derived maps.
const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const APP = path.join(ROOT, "src", "app");
const OUT = path.join(ROOT, "src", "content", "lastmod.generated.ts");

try {
  execSync("git rev-parse --git-dir", { cwd: ROOT, stdio: "pipe" });
} catch {
  console.log("[gen-lastmod] no git available (server build) - keeping committed file");
  process.exit(0);
}

// route -> view module, same walk extract-meta.cjs uses.
const routes = [];
(function walk(dir, base) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) walk(path.join(dir, e.name), base + "/" + e.name);
    else if (e.name === "page.tsx") {
      const pathName = base || "/";
      if (pathName.includes("[")) continue;
      const src = fs.readFileSync(path.join(dir, e.name), "utf8");
      const m = src.match(/(?:import\s+\w+|export\s*\{\s*default\s*\})\s+from\s+"@\/views\/([^"]+)"/);
      if (m) routes.push({ pathName, view: `src/views/${m[1]}.tsx` });
    }
  }
})(APP, "");

// One `git log` per FILE is slow at 589 routes; ask git once for every commit date + files.
const dates = {};
const log = execSync('git log --format="~%cs" --name-only -- src/views', {
  cwd: ROOT, maxBuffer: 64 * 1024 * 1024, encoding: "utf8",
});
let cur = null;
for (const line of log.split("\n")) {
  if (line.startsWith("~")) cur = line.slice(1);
  else if (line && cur && !(line in dates)) dates[line] = cur; // first hit = newest commit
}

const map = {};
let hit = 0;
for (const r of routes) {
  const d = dates[r.view];
  if (d) { map[r.pathName] = d; hit++; }
}
const body =
  "// AUTO-GENERATED by scripts/gen-lastmod.cjs - do not edit by hand. COMMITTED on purpose:\n" +
  "// the server build has no .git to regenerate from. Re-runs on every local prebuild.\n" +
  "export const LASTMOD: Record<string, string> = " + JSON.stringify(map, null, 0) + ";\n";
fs.writeFileSync(OUT, body);
const uniq = new Set(Object.values(map)).size;
console.log(`[gen-lastmod] wrote ${hit}/${routes.length} routes, ${uniq} distinct dates`);
